/* global Office */
import React, { useEffect, useState } from "react";
import { createRoot } from "react-dom/client";
import {
  FluentProvider,
  webLightTheme,
  Title3,
  Body1,
  Button,
  Spinner,
  Card,
  CardHeader,
  CardFooter,
  Badge,
} from "@fluentui/react-components";
import { Dismiss24Regular, DocumentPdf24Regular } from "@fluentui/react-icons";

export const PreviewDialog: React.FC = () => {
  const [isOfficeReady, setIsOfficeReady] = useState(false);

  useEffect(() => {
    Office.onReady(() => {
      setIsOfficeReady(true);

      // Tangkap pesan dari parent taskpane jika ada pengiriman blob/URL PDF
      if (Office.context && Office.context.ui) {
        // Dialog handler
      }
    });
  }, []);

  const handleClose = () => {
    try {
      Office.context.ui.messageParent(JSON.stringify({ action: "CLOSE_DIALOG" }));
    } catch {
      window.close();
    }
  };

  if (!isOfficeReady) {
    return (
      <FluentProvider theme={webLightTheme}>
        <div style={{ display: "flex", justifyContent: "center", alignItems: "center", height: "100vh" }}>
          <Spinner label="Memuat Office runtime..." />
        </div>
      </FluentProvider>
    );
  }

  return (
    <FluentProvider theme={webLightTheme}>
      <div style={{ padding: "24px", maxWidth: "900px", margin: "0 auto", fontFamily: "Segoe UI, sans-serif" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "16px" }}>
          <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
            <DocumentPdf24Regular style={{ color: "#d13438" }} />
            <Title3>Pratinjau PDF Penuh</Title3>
            <Badge appearance="tint" color="informative">Fase P1</Badge>
          </div>
          <Button
            appearance="subtle"
            icon={<Dismiss24Regular />}
            onClick={handleClose}
            aria-label="Tutup pratinjau"
          />
        </div>

        <Card style={{ padding: "24px", textAlign: "center", minHeight: "350px", display: "flex", flexDirection: "column", justifyContent: "center", alignItems: "center", background: "#f8f9fa", border: "1px dashed #d1d5db" }}>
          <CardHeader
            header={
              <Body1 style={{ fontWeight: 600, fontSize: "16px" }}>
                Integrasi Penampil PDF Penuh (pdf.js)
              </Body1>
            }
          />
          <div style={{ margin: "16px 0", maxWidth: "520px", color: "#605e5c", lineHeight: "1.6" }}>
            <Body1>
              Fitur pratinjau PDF interaktif per-halaman beresolusi penuh menggunakan PDF.js dijadwalkan untuk rilis Fase P1.
              <br /><br />
              Untuk saat ini, gunakan <strong>Quick Preview</strong> skematik di panel samping untuk memeriksa tata letak dan batas margin, lalu klik <strong>Ekspor PDF</strong> untuk mengunduh dokumen siap cetak.
            </Body1>
          </div>
          <CardFooter>
            <Button appearance="primary" onClick={handleClose}>
              Kembali ke Panel Cetak
            </Button>
          </CardFooter>
        </Card>
      </div>
    </FluentProvider>
  );
};

// Mount component ke DOM di dialog.html
const container = document.getElementById("dialog-root");
if (container) {
  const root = createRoot(container);
  root.render(<PreviewDialog />);
}
